1338		config := `{
1339		  "routes": [
1340		    {"id": "zeta",  "methods": ["GET"], "pathPrefix": "/api", "upstream": "http://z.internal/v1"},
1341		    {"id": "alpha", "methods": ["GET"], "pathPrefix": "/api", "upstream": "http://a.internal/v1"},
1342		    {"id": "wild",  "methods": ["*"],   "pathPrefix": "/api", "upstream": "http://w.internal/v1"}
1343		  ]
1344		}`
1345		res := runResolveCLI(t, config, cliSuccessRequest)
1346	
1347		if res.exitCode == 0 {
1348			t.Fatalf("exit code = 0, want non-zero")
1349		}
1350		if len(res.stdout) != 0 {
1351			t.Fatalf("stdout = %q, want completely empty on failure", res.stdout)
1352		}
1353	
1354		var fail struct {
1355			Code       string   `json:"code"`
1356			Reason     string   `json:"reason"`
1357			Candidates []string `json:"candidates"`
1358		}
