// TestResolveCLIUnbracketedIPv6Host drives the missing-bracket rule at the
// command boundary: a full, compressed or IPv4-tail IPv6 literal written
// without square brackets — with a digit suffix, a zone or userinfo too —
// rejects the whole config up front, even on a route the request never
// hits. Non-zero exit, completely empty stdout and one JSON invalid_config
// error on stderr whose reason names the route position, its id and the
// upstream field and says the IPv6 host is missing brackets; it must not be
// reported as broken config JSON, and an invalid request still loses to the
// config error.
func TestResolveCLIUnbracketedIPv6Host(t *testing.T) {
	cases := []struct {
		name     string
		upstream string
	}{
		{"compressed address under base path", "http://2001:db8::1/base"},
		{"compressed address with trailing digits", "http://::1:8080/base"},
		{"embedded ipv4 tail", "http://::ffff:192.0.2.1/base"},
		{"full form", "http://2001:0db8:0000:0000:0000:0000:0000:0001/base"},
		{"address and trailing digits, no base path", "http://fe80::1:8080"},
		{"percent encoded zone without brackets", "http://fe80::1%25eth0/base"},
		{"encoded userinfo and a port-like suffix", "https://user:p%40ss@2001:db8::1:8443/base"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			config := `{
			  "routes": [
			    {"id": "api", "methods": ["GET"], "pathPrefix": "/api", "upstream": "http://api.internal/v1"},
			    {"id": "admin", "methods": ["GET"], "pathPrefix": "/admin", "upstream": "` + tc.upstream + `"}
			  ]
			}`
			// The request hits the valid first route only.
			res := runResolveCLI(t, config, cliSuccessRequest)

			if res.exitCode == 0 {
				t.Fatalf("exit code = 0, want non-zero")
			}
			if len(res.stdout) != 0 {
				t.Fatalf("stdout = %q, want completely empty on failure", res.stdout)
			}
			var fail struct {
				Code   string `json:"code"`
				Reason string `json:"reason"`
			}
			decodeOneJSON(t, res.stderr, "stderr", &fail)
			if fail.Code != "invalid_config" {
				t.Fatalf("code = %q, want invalid_config", fail.Code)
			}
			for _, want := range []string{"route 2", `"admin"`, "upstream", "IPv6", "bracket"} {
				if !strings.Contains(fail.Reason, want) {
					t.Errorf("reason = %q, want substring %q", fail.Reason, want)
				}
			}
			if strings.Contains(fail.Reason, "not valid JSON") {
				t.Errorf("an unbracketed IPv6 host is a content error, not a JSON syntax failure: %q", fail.Reason)
			}
		})
	}

	// An unbracketed-IPv6 config wins over an invalid request: config
	// validation precedes request parsing, so even broken request JSON yields
	// invalid_config.
	config := `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/x","upstream":"http://2001:db8::1/base"}]}`
	res := runResolveCLI(t, config, `{not json`)
	if res.exitCode == 0 || len(res.stdout) != 0 {
		t.Fatalf("got exit %d stdout %q, want non-zero exit and empty stdout", res.exitCode, res.stdout)
	}
	var fail struct {
		Code string `json:"code"`
	}
	decodeOneJSON(t, res.stderr, "stderr", &fail)
	if fail.Code != "invalid_config" {
		t.Fatalf("code = %q, want invalid_config to take priority", fail.Code)
	}
}

// TestResolveCLIValidIPv6Upstreams drives the legal IPv6 spellings at the
// command boundary: full, compressed and IPv4-tail literals, a port,
// percent-encoded userinfo and a percent-encoded zone must resolve and keep
// the configured bytes verbatim; ordinary domains and bare IPv4 hosts keep
// their existing behavior.
// TestResolveCLIBracketedHostShape drives the whole-host bracket grammar at
// the command boundary: brackets must wrap the whole host exactly once, so a
// repeated bracket group ("[::1][::2]"), a stray ']' ("[::1]extra]") or junk
// between the address and the port rejects the whole config up front — even
// when userinfo or a port is present and even though the request only hits
// the valid first route. Failure keeps the usual contract: non-zero exit,
// completely empty stdout and one JSON invalid_config error on stderr whose
// reason names the route position, its id and the upstream field and calls
// the bracket spelling illegal rather than blaming the document's JSON.
func TestResolveCLIBracketedHostShape(t *testing.T) {
	cases := []struct {
		name     string
		upstream string
	}{
		{"repeated bracket group", "http://[::1][::2]/v1"},
		{"text and a stray closing bracket", "http://[::1]extra]/v1"},
		{"repeated bracket group after a port", "http://[::1]:8080[::2]/v1"},
		{"userinfo with a repeated bracket group", "https://user:p%40ss@[::1][::2]/v1"},
		{"userinfo with text and a stray bracket", "https://user:p%40ss@[::1]extra]/v1"},
		{"userinfo with junk after the port", "https://user:p%40ss@[::1]:8443x/v1"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			config := `{
			  "routes": [
			    {"id": "api", "methods": ["GET"], "pathPrefix": "/api", "upstream": "http://api.internal/v1"},
			    {"id": "admin", "methods": ["GET"], "pathPrefix": "/admin", "upstream": "` + tc.upstream + `"}
			  ]
			}`
			// The request hits the valid first route only.
			res := runResolveCLI(t, config, cliSuccessRequest)

			if res.exitCode == 0 {
				t.Fatalf("exit code = 0, want non-zero")
			}
			if len(res.stdout) != 0 {
				t.Fatalf("stdout = %q, want completely empty on failure", res.stdout)
			}
			var fail struct {
				Code   string `json:"code"`
				Reason string `json:"reason"`
			}
			decodeOneJSON(t, res.stderr, "stderr", &fail)
			if fail.Code != "invalid_config" {
				t.Fatalf("code = %q, want invalid_config", fail.Code)
			}
			for _, want := range []string{"route 2", `"admin"`, "upstream", "bracketed host", "IPv6"} {
				if !strings.Contains(fail.Reason, want) {
					t.Errorf("reason = %q, want substring %q", fail.Reason, want)
				}
			}
			if strings.Contains(fail.Reason, "not valid JSON") {
				t.Errorf("an illegal bracketed host is a content error, not a JSON syntax failure: %q", fail.Reason)
			}
		})
	}

	// A valid literal with userinfo, a port, an encoded base path and an
	// encoded-slash query still resolves byte for byte through the boundary.
	config := `{"routes":[{"id":"api","methods":["GET"],"pathPrefix":"/api",
	  "upstream":"https://user:p%40ss@[2001:DB8::1]:8443/v%2f"}]}`
	success := assertResolveSuccess(t, runResolveCLI(t, config,
		`{"method":"GET","target":"/api/x?q=%2f"}`))
	if success.RouteID != "api" {
		t.Errorf("routeId = %q, want api", success.RouteID)
	}
	if want := "https://user:p%40ss@[2001:DB8::1]:8443/v%2f/x?q=%2f"; success.UpstreamURL != want {
		t.Errorf("upstreamURL = %q, want %q", success.UpstreamURL, want)
	}
}

func TestResolveCLIValidIPv6Upstreams(t *testing.T) {
	cases := []struct {
		name     string
		prefix   string
		upstream string
		target   string
		wantURL  string
	}{
		{
			name:     "compressed literal with userinfo, port and encoded path",
			prefix:   "/api",
			upstream: "https://user:p%40ss@[2001:db8::1]:8443/v%2f",
			target:   "/api/orders?a=1&a=",
			wantURL:  "https://user:p%40ss@[2001:db8::1]:8443/v%2f/orders?a=1&a=",
		},
		{
			name:     "encoded zone keeps its original spelling",
			prefix:   "/",
			upstream: "https://[fe80::1%25eth0]/base",
			target:   "/x",
			wantURL:  "https://[fe80::1%25eth0]/base/x",
		},
		{
			name:     "full form literal",
			prefix:   "/",
			upstream: "http://[2001:0db8:0000:0000:0000:0000:0000:0001]/b",
			target:   "/x",
			wantURL:  "http://[2001:0db8:0000:0000:0000:0000:0000:0001]/b/x",
		},
		{
			name:     "ipv4 tail and port",
			prefix:   "/",
			upstream: "http://[::ffff:192.168.0.1]:8080/b",
			target:   "/x",
			wantURL:  "http://[::ffff:192.168.0.1]:8080/b/x",
		},
		{
			name:     "ordinary domain is unaffected",
			prefix:   "/api",
			upstream: "http://api.internal/v1",
			target:   "/api/x?y=1",
			wantURL:  "http://api.internal/v1/x?y=1",
		},
		{
			name:     "bare ipv4 host without brackets is unaffected",
			prefix:   "/api",
			upstream: "http://127.0.0.1:8080/v1",
			target:   "/api/x",
			wantURL:  "http://127.0.0.1:8080/v1/x",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			config := `{"routes":[{"id":"r","methods":["GET"],"pathPrefix":"` + tc.prefix +
				`","upstream":"` + tc.upstream + `"}]}`
			request := `{"method":"GET","target":"` + tc.target + `"}`
			success := assertResolveSuccess(t, runResolveCLI(t, config, request))
			if success.RouteID != "r" {
				t.Errorf("routeId = %q, want r", success.RouteID)
			}
			if success.UpstreamURL != tc.wantURL {
				t.Errorf("upstreamURL = %q, want %q", success.UpstreamURL, tc.wantURL)
			}
		})
	}
}

func TestResolveCLIRouteConflict(t *testing.T) {
	// alpha and zeta both concretely accept GET at the same /api prefix
	// with no longer prefix to win; the same-prefix wildcard route must not
	// appear among the final candidates.
	config := `{
	  "routes": [
	    {"id": "zeta",  "methods": ["GET"], "pathPrefix": "/api", "upstream": "http://z.internal/v1"},
	    {"id": "alpha", "methods": ["GET"], "pathPrefix": "/api", "upstream": "http://a.internal/v1"},
	    {"id": "wild",  "methods": ["*"],   "pathPrefix": "/api", "upstream": "http://w.internal/v1"}
	  ]
	}`
	res := runResolveCLI(t, config, cliSuccessRequest)

	if res.exitCode == 0 {
		t.Fatalf("exit code = 0, want non-zero")
	}
	if len(res.stdout) != 0 {
		t.Fatalf("stdout = %q, want completely empty on failure", res.stdout)
	}

	var fail struct {
		Code       string   `json:"code"`
		Reason     string   `json:"reason"`
		Candidates []string `json:"candidates"`
	}
	decodeOneJSON(t, res.stderr, "stderr", &fail)
	if fail.Code != "route_conflict" {
		t.Errorf("code = %q, want route_conflict", fail.Code)
	}
	if fail.Reason == "" {
		t.Fatal("reason must be non-empty")
	}
	wantCandidates := []string{"alpha", "zeta"}
	if !reflect.DeepEqual(fail.Candidates, wantCandidates) {
		t.Errorf("candidates = %v, want %v (sorted, wildcard excluded)", fail.Candidates, wantCandidates)
	}
}

package contractsentinel

import (
	"encoding/json"
	"fmt"
	"strings"
	"sync"
	"testing"
)

func transformConfig(t *testing.T, transforms string) *Config {
	t.Helper()
	src := `{"routes":[{"id":"r1","methods":["*"],"pathPrefix":"/","upstream":"http://h.internal/base","queryTransforms":` + transforms + `}]}`
	return mustConfig(t, src)
}

func transformResult(t *testing.T, transforms, target string) string {
	t.Helper()
	cfg := transformConfig(t, transforms)
	res := resolveJSON(t, cfg, `{"method":"GET","target":"`+target+`"}`)
	return res.UpstreamURL
}

func TestQueryTransformSpecExample(t *testing.T) {
	// x=%2f&a=1&%61=2&flag, then set a="" and remove flag -> x=%2f&a=
	rules := `[{"op":"set","name":"a","value":""},{"op":"remove","name":"flag"}]`
	got := transformResult(t, rules, "/p?x=%2f&a=1&%61=2&flag")
	want := "http://h.internal/base/p?x=%2f&a="
	if got != want {
		t.Fatalf("upstreamURL = %q, want %q", got, want)
	}
}

func TestQueryTransformSet(t *testing.T) {
	cases := []struct {
		name      string
		rules     string
		target    string
		wantQuery string // expected suffix after http://h.internal/base/p
	}{
		{
			name:      "set merges all duplicates at first hit",
			rules:     `[{"op":"set","name":"a","value":"9"}]`,
			target:    "/p?z=0&a=1&a=2&b=3",
			wantQuery: "?z=0&a=9&b=3",
		},
		{
			name:      "set matches percent-decoded duplicate names",
			rules:     `[{"op":"set","name":"a","value":""}]`,
			target:    "/p?a=1&%61=2",
			wantQuery: "?a=",
		},
		{
			name:      "set matches plus-as-space names",
			rules:     `[{"op":"set","name":"a b","value":"x"}]`,
			target:    "/p?a+b=1",
			wantQuery: "?a%20b=x",
		},
		{
			name:      "set hits parameters without an equals sign",
			rules:     `[{"op":"set","name":"flag","value":"on"}]`,
			target:    "/p?flag&x=1",
			wantQuery: "?flag=on&x=1",
		},
		{
			name:      "set replaces valueless parameter with empty value verbatim style",
			rules:     `[{"op":"set","name":"flag","value":""}]`,
			target:    "/p?flag",
			wantQuery: "?flag=",
		},
		{
			name:      "set appends an absent name at the end",
			rules:     `[{"op":"set","name":"new","value":"v"}]`,
			target:    "/p?a=1&b=2",
			wantQuery: "?a=1&b=2&new=v",
		},
		{
			name:      "set appends after an empty trailing fragment",
			rules:     `[{"op":"set","name":"n","value":"v"}]`,
			target:    "/p?a=1&",
			wantQuery: "?a=1&&n=v",
		},
		{
			name:      "set creates a query string when there is none",
			rules:     `[{"op":"set","name":"a","value":"1"}]`,
			target:    "/p",
			wantQuery: "?a=1",
		},
		{
			name:      "set on empty question mark adds the parameter",
			rules:     `[{"op":"set","name":"a","value":"1"}]`,
			target:    "/p?",
			wantQuery: "?a=1",
		},
		{
			name:      "set is case sensitive",
			rules:     `[{"op":"set","name":"A","value":"2"}]`,
			target:    "/p?a=1",
			wantQuery: "?a=1&A=2",
		},
		{
			name:      "set encodes spaces utf8 and reserved characters",
			rules:     `[{"op":"set","name":"k y","value":"héllo /&=?"}]`,
			target:    "/p",
			wantQuery: "?k%20y=h%C3%A9llo%20%2F%26%3D%3F",
		},
		{
			name:      "set keeps unreserved characters raw",
			rules:     `[{"op":"set","name":"a-b_c.d~e","value":"-._~"}]`,
			target:    "/p",
			wantQuery: "?a-b_c.d~e=-._~",
		},
		{
			name:      "set uses value literally including an equals sign",
			rules:     `[{"op":"set","name":"a","value":"x=y"}]`,
			target:    "/p?a=old",
			wantQuery: "?a=x%3Dy",
		},
		{
			name:      "unmodified values keep their original lowercase escapes",
			rules:     `[{"op":"set","name":"a","value":""}]`,
			target:    "/p?x=%2f&a=1",
			wantQuery: "?x=%2f&a=",
		},
		{
			name:      "rules chain on the previous result",
			rules:     `[{"op":"set","name":"a","value":"1"},{"op":"set","name":"a","value":"2"}]`,
			target:    "/p",
			wantQuery: "?a=2",
		},
		{
			name:      "set then remove of the same name drops the query",
			rules:     `[{"op":"set","name":"a","value":"1"},{"op":"remove","name":"a"}]`,
			target:    "/p?b=2",
			wantQuery: "?b=2",
		},
		{
			name:      "remove then set appends since the name is now absent",
			rules:     `[{"op":"remove","name":"a"},{"op":"set","name":"a","value":"z"}]`,
			target:    "/p?a=1&a=2&b=3",
			wantQuery: "?b=3&a=z",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := transformResult(t, tc.rules, tc.target)
			want := buildWant(tc.target, tc.wantQuery)
			if got != want {
				t.Errorf("upstreamURL = %q, want %q", got, want)
			}
		})
	}
}

func TestQueryTransformSetSpecialCharNames(t *testing.T) {
	// A rule's name and value are literal text: '&', '=', '%' and '+' inside
	// them are data, never query structure. On the request side only a raw
	// '&' separates fragments and only the first raw '=' of a fragment splits
	// name from value, so an encoded "&" or "=" stays inside one name.
	cases := []struct {
		name      string
		rules     string
		target    string
		wantQuery string // expected suffix after http://h.internal/base/p
	}{
		{
			// Both sources decode to the same name (lowercase and uppercase
			// hex alike) and merge at the first hit's position; the encoded
			// '&' and '=' in the replacement cannot split out extra
			// parameters, and untouched fragments, the empty fragment and the
			// order all keep their original bytes.
			name:      "name and value with ampersand and equals merge at first hit",
			rules:     `[{"op":"set","name":"a&b=c","value":"x&y=z"}]`,
			target:    "/p?keep=%2f+&a%26b%3dc=1&&a%26b%3Dc=2&tail=",
			wantQuery: "?keep=%2f+&a%26b%3Dc=x%26y%3Dz&&tail=",
		},
		{
			name:      "valueless parameter with encoded name gains an equals sign",
			rules:     `[{"op":"set","name":"a&b=c","value":"v"}]`,
			target:    "/p?a%26b%3Dc",
			wantQuery: "?a%26b%3Dc=v",
		},
		{
			// The fragment "a=b=1" has name "a" and value "b=1": the rule
			// name "a=b" must not match it, so it is appended instead.
			name:      "first raw equals splits, so a=b=1 is not named a=b",
			rules:     `[{"op":"set","name":"a=b","value":"v"}]`,
			target:    "/p?a=b=1",
			wantQuery: "?a=b=1&a%3Db=v",
		},
		{
			name:      "encoded equals in the request name matches a literal equals",
			rules:     `[{"op":"set","name":"a=b","value":"v"}]`,
			target:    "/p?a%3Db=1",
			wantQuery: "?a%3Db=v",
		},
		{
			// The literal name "%26" decodes one level further than "&": it
			// matches only "%2526", never the "%26" that decodes to "&".
			name:      "literal percent escape name matches only its double-encoded form",
			rules:     `[{"op":"set","name":"%26","value":"v"}]`,
			target:    "/p?%26=1&%2526=2",
			wantQuery: "?%26=1&%2526=v",
		},
		{
			// The literal name "a+b" contains a real plus: it matches only
			// "a%2Bb". A raw '+' and "%20" both decode to a space, and a
			// decoded '+' never turns back into a space.
			name:      "literal plus name matches encoded plus only, not space forms",
			rules:     `[{"op":"set","name":"a+b","value":"v"}]`,
			target:    "/p?a+b=1&a%2Bb=2&a%20b=3",
			wantQuery: "?a+b=1&a%2Bb=v&a%20b=3",
		},
		{
			name:      "space name does not match an encoded plus",
			rules:     `[{"op":"set","name":"a b","value":"v"}]`,
			target:    "/p?a%2Bb=1",
			wantQuery: "?a%2Bb=1&a%20b=v",
		},
		{
			name:      "literal percent in the name is encoded and matched as %25",
			rules:     `[{"op":"set","name":"100%","value":"v"}]`,
			target:    "/p?100%25=1",
			wantQuery: "?100%25=v",
		},
		{
			name:      "absent special name is appended after a trailing empty fragment",
			rules:     `[{"op":"set","name":"x&y","value":"v"}]`,
			target:    "/p?a=1&",
			wantQuery: "?a=1&&x%26y=v",
		},
		{
			name:      "absent special name creates the query string",
			rules:     `[{"op":"set","name":"x&y","value":"="}]`,
			target:    "/p",
			wantQuery: "?x%26y=%3D",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := transformResult(t, tc.rules, tc.target)
			want := buildWant(tc.target, tc.wantQuery)
			if got != want {
				t.Errorf("upstreamURL = %q, want %q", got, want)
			}
		})
	}
}

func TestQueryTransformSetSpecialNamesDoNotAffectRouting(t *testing.T) {
	// Special characters in parameter names are query content only: route
	// selection and path joining are decided before transforms run and must
	// be unaffected by them.
	cfg := mustConfig(t, `{"routes":[
	  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://api.internal/v1",
	   "queryTransforms":[{"op":"set","name":"a&b=c","value":"x&y=z"}]},
	  {"id":"root","methods":["*"],"pathPrefix":"/","upstream":"http://root.internal"}
	]}`)

	res := resolveJSON(t, cfg, `{"method":"GET","target":"/api/x/y?keep=%2f+&a%26b%3dc=1"}`)
	if res.RouteID != "api" {
		t.Errorf("routeId = %q, want api", res.RouteID)
	}
	if want := "http://api.internal/v1/x/y?keep=%2f+&a%26b%3Dc=x%26y%3Dz"; res.UpstreamURL != want {
		t.Errorf("upstreamURL = %q, want %q", res.UpstreamURL, want)
	}

	// The same query on a path that only the transform-free root route
	// matches is preserved byte for byte.
	res = resolveJSON(t, cfg, `{"method":"GET","target":"/other?a%26b%3dc=1&keep=%2f+"}`)
	if res.RouteID != "root" {
		t.Errorf("routeId = %q, want root", res.RouteID)
	}
	if want := "http://root.internal/other?a%26b%3dc=1&keep=%2f+"; res.UpstreamURL != want {
		t.Errorf("upstreamURL = %q, want %q", res.UpstreamURL, want)
	}
}

func TestQueryTransformSetInvalidEscapeNoPartialSuccess(t *testing.T) {
	// A malformed percent escape anywhere in the target fails the whole
	// request as invalid_request, even when another parameter would have
	// been replaced by the set rule: no partially rewritten query may come
	// back as a success.
	cfg := transformConfig(t, `[{"op":"set","name":"a&b=c","value":"x&y=z"}]`)
	targets := []string{
		"/p?a%26b%3dc=1&bad%zz=2", // bad escape after a replaceable parameter
		"/p?bad%zz=2&a%26b%3dc=1", // bad escape before a replaceable parameter
		"/p?a%26b%zz=1",           // bad escape inside the target name itself
		"/p?a%26b%3dc=1%2",        // truncated escape in the replaceable value
	}
	for _, target := range targets {
		// The front door: ParseRequest rejects the target outright.
		_, rf := ParseRequest([]byte(`{"method":"GET","target":"` + target + `"}`))
		if rf == nil || rf.Code != "invalid_request" {
			t.Fatalf("ParseRequest(%q): got %+v, want invalid_request", target, rf)
		}
		// A caller that bypasses ParseRequest still gets invalid_request from
		// Resolve whenever the malformed escape sits in a decoded name, and
		// never a partial Resolution.
		res, rf := Resolve(cfg, &Request{Method: "GET", Target: target})
		if rf != nil && rf.Code != "invalid_request" {
			t.Fatalf("Resolve(%q): got code %q, want invalid_request", target, rf.Code)
		}
		if res != nil && rf != nil {
			t.Fatalf("Resolve(%q): got both %+v and %+v, want at most one", target, res, rf)
		}
	}

	// A bad escape in a name that the set rule would have replaced is always
	// caught, even via Resolve directly.
	for _, target := range []string{"/p?a%26b%zz=1", "/p?bad%zz=2&a%26b%3dc=1"} {
		res, rf := Resolve(cfg, &Request{Method: "GET", Target: target})
		if rf == nil || rf.Code != "invalid_request" {
			t.Fatalf("Resolve(%q): got %+v, want invalid_request", target, rf)
		}
		if res != nil {
			t.Fatalf("Resolve(%q): got partial success %+v, want no resolution", target, res)
		}
	}
}

func TestQueryTransformRemove(t *testing.T) {
	cases := []struct {
